package io.github.jesterportfolio.hearth.survival.enchants;
import java.util.*;
import org.bukkit.*;import org.bukkit.inventory.*;import org.bukkit.persistence.PersistentDataType;
import net.kyori.adventure.text.Component;
/** PDC는 정본이고 lore는 별도 소유 component다. 알 수 없는 버전은 덮어쓰지 않는다. */
public final class EnchantItems {
    public enum Kind { BOOK,UNIDENTIFIED,PROTECTION,BOOST }
    public record Book(String id,int level,double success,double destroy,Kind kind,double boost){public Book{if(!id.matches("hearth:[a-z][a-z0-9_]{0,48}")||level<1||level>1000||!Double.isFinite(success)||success<0||success>1||!Double.isFinite(destroy)||destroy<0||destroy>1||!Double.isFinite(boost)||boost<0||boost>1)throw new IllegalArgumentException("ENCHANT_BOOK");}}
    private final NamespacedKey data,book;private final Map<String,Map<String,Integer>> cache=new LinkedHashMap<>(128,.75f,true){protected boolean removeEldestEntry(Map.Entry<String,Map<String,Integer>> e){return size()>4096;}};
    public EnchantItems(org.bukkit.plugin.Plugin plugin){data=new NamespacedKey(plugin,"enchants_v1");book=new NamespacedKey(plugin,"enchant_book_v1");}
    public Map<String,Integer> read(ItemStack item){if(item==null||item.isEmpty()||!item.hasItemMeta())return Map.of();String raw=item.getItemMeta().getPersistentDataContainer().get(data,PersistentDataType.STRING);if(raw==null)return Map.of();if(raw.length()>8192||!raw.startsWith("1;"))throw new IllegalArgumentException("ENCHANT_DATA_VERSION");var cached=cache.get(raw);if(cached!=null)return cached;var out=new LinkedHashMap<String,Integer>();for(String row:raw.substring(2).split(";")){if(row.isEmpty())continue;String[] pair=row.split("=");if(pair.length!=2||!pair[0].matches("hearth:[a-z][a-z0-9_]{0,48}"))throw new IllegalArgumentException("ENCHANT_ITEM_DATA");int value=Integer.parseInt(pair[1]);if(value<1||value>1000||out.size()>=64||out.put(pair[0],value)!=null)throw new IllegalArgumentException("ENCHANT_ITEM_DATA");}var result=Map.copyOf(out);cache.put(raw,result);return result;}
    public ItemStack write(ItemStack original,Map<String,Integer> values){read(original);var item=original.clone();var sorted=new TreeMap<>(values);if(sorted.size()>64)throw new IllegalArgumentException("ENCHANT_ITEM_LIMIT");StringBuilder raw=new StringBuilder("1;");sorted.forEach((id,level)->{if(!id.matches("hearth:[a-z][a-z0-9_]{0,48}")||level<1||level>1000)throw new IllegalArgumentException("ENCHANT_ITEM_DATA");raw.append(id).append('=').append(level).append(';');});item.editMeta(meta->{if(values.isEmpty())meta.getPersistentDataContainer().remove(data);else meta.getPersistentDataContainer().set(data,PersistentDataType.STRING,raw.toString());var lore=new ArrayList<Component>(meta.lore()==null?List.of():meta.lore());lore.removeIf(line->"hearth:enchant_lore_v1".equals(line.insertion()));if(!values.isEmpty()){lore.add(Component.text("Hearth 특수 인챈트").insertion("hearth:enchant_lore_v1"));sorted.forEach((id,level)->lore.add(Component.text(id+" · "+level).insertion("hearth:enchant_lore_v1")));}meta.lore(lore);});return item;}
    public ItemStack book(Book value){var item=new ItemStack(Material.BOOK);item.editMeta(meta->{meta.displayName(Component.text(value.kind()==Kind.UNIDENTIFIED?"미감정 특수 인챈트북":value.kind()==Kind.PROTECTION?"장비 보호 주문서":value.kind()==Kind.BOOST?"성공률 증가 재료":value.id()+" · "+value.level()));meta.lore(List.of(Component.text("적용 성공 "+Math.round(value.success()*100)+"% · 실패 시 파괴 "+Math.round(value.destroy()*100)+"%")));meta.getPersistentDataContainer().set(book,PersistentDataType.STRING,"1;"+value.id()+";"+value.level()+";"+value.success()+";"+value.destroy()+";"+value.kind()+";"+value.boost());});return item;}
    public Optional<Book> book(ItemStack item){if(item==null||item.isEmpty()||!item.hasItemMeta())return Optional.empty();String raw=item.getItemMeta().getPersistentDataContainer().get(book,PersistentDataType.STRING);if(raw==null)return Optional.empty();String[] p=raw.split(";");if(p.length!=7||!p[0].equals("1"))throw new IllegalArgumentException("ENCHANT_BOOK_VERSION");return Optional.of(new Book(p[1],Integer.parseInt(p[2]),Double.parseDouble(p[3]),Double.parseDouble(p[4]),Kind.valueOf(p[5]),Double.parseDouble(p[6])));}
    public static boolean matches(String type,Material material){String name=material.name();return switch(type){case "any"->true;case "armor"->name.endsWith("_HELMET")||name.endsWith("_CHESTPLATE")||name.endsWith("_LEGGINGS")||name.endsWith("_BOOTS");case "helmet"->name.endsWith("_HELMET")||name.equals("TURTLE_HELMET");case "boots"->name.endsWith("_BOOTS");case "sword"->name.endsWith("_SWORD");case "bow"->material==Material.BOW||material==Material.CROSSBOW;case "axe"->name.endsWith("_AXE");case "pickaxe"->name.endsWith("_PICKAXE");case "hoe"->name.endsWith("_HOE");case "tool"->name.endsWith("_PICKAXE")||name.endsWith("_AXE")||name.endsWith("_SHOVEL")||name.endsWith("_HOE")||material==Material.SHEARS;case "damaged-items"->material.getMaxDurability()>0;default->false;};}
}
